<script>
 import {getAvatarFromTeamManagers,getTeamNameFromTeamManagers} from '$lib/utils/helperFunctions/universalFunctions';
 export let previousDrafts=[];export let leagueTeamManagers=[];export let players={};
 const drafts=(previousDrafts||[]).filter(d=>d?.draft?.length&&d?.draftOrder?.length).sort((a,b)=>+b.year-+a.year);let selectedYear=drafts[0]?.year;
 $: selected=drafts.find(d=>String(d.year)===String(selectedYear));$: analysis=selected?analyze(selected):null;
 const externalLists={
  2025:['Josh Allen','Lamar Jackson','Jayden Daniels','Jalen Hurts','Joe Burrow','Patrick Mahomes II','JaMar Chase','Bijan Robinson','Baker Mayfield','Saquon Barkley','Bo Nix','CeeDee Lamb','Justin Jefferson','Jahmyr Gibbs','Kyler Murray','Dak Prescott','Nico Collins','Derrick Henry','Brian Thomas Jr','Malik Nabers','Justin Fields','Puka Nacua','Brock Purdy','Justin Herbert','Amon-Ra St Brown','Ashton Jeanty','Christian McCaffrey','Caleb Williams','Drake Maye','Jonathan Taylor','Drake London','Jared Goff','AJ Brown','Josh Jacobs','George Kittle','Jordan Love','Brock Bowers','Bucky Irving','Ladd McConkey','DeVon Achane','Kyren Williams','Trevor Lawrence','Chase Brown','Tee Higgins','CJ Stroud','Mike Evans','Trey McBride','James Cook','JJ McCarthy','Jaxon Smith-Njigba','Tyreek Hill','Davante Adams','Omarion Hampton','Marvin Harrison Jr','Kenneth Walker III','Garrett Wilson','Terry McLaurin','DK Metcalf','Breece Hall','Chuba Hubbard','Bryce Young','Tua Tagovailoa','James Conner','Courtland Sutton','TreVeyon Henderson','Jameson Williams','Alvin Kamara','DJ Moore','Geno Smith','Xavier Worthy','Michael Penix Jr','Matthew Stafford','Calvin Ridley','Tetairoa McMillan','George Pickens','DeVonta Smith','David Montgomery','DAndre Swift','Zay Flowers','Tony Pollard','RJ Harvey','Sam LaPorta','Isiah Pacheco','Cam Ward','Sam Darnold','Jaylen Waddle','Aaron Jones Sr','Mark Andrews','Kaleb Johnson','Travis Hunter','TJ Hockenson','Tyrone Tracy Jr','Ricky Pearsall','Rome Odunze','Rashee Rice','Chris Olave','Jordan Mason','Jerry Jeudy','Emeka Egbuka','Travis Kelce'],
  2024:['Josh Allen','Jalen Hurts','Patrick Mahomes II','Lamar Jackson','Anthony Richardson','CJ Stroud','Christian McCaffrey','Kyler Murray','CeeDee Lamb','Tyreek Hill','Joe Burrow','JaMar Chase','Dak Prescott','Breece Hall','Bijan Robinson','Amon-Ra St Brown','Jordan Love','Justin Jefferson','AJ Brown','Jayden Daniels','Garrett Wilson','Brock Purdy','Jonathan Taylor','Jahmyr Gibbs','Caleb Williams','Puka Nacua','Tua Tagovailoa','Saquon Barkley','Jared Goff','Marvin Harrison Jr','Trevor Lawrence','Derrick Henry','Drake London','Kyren Williams','Davante Adams']
 };
 const norm=s=>(s||'').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,'').replace(/(jr|sr|ii|iii)$/,'');
 const rankMap=y=>Object.fromEntries((externalLists[y]||[]).map((n,i)=>[norm(n),i+1]));
 function rp(d,r,c){let R=r+1,n=d.draftOrder.length;if(d.draftType==='snake'&&!d.reversalRound)return R%2===0?n-c:c+1;if(d.draftType==='snake'&&d.reversalRound){if((R<d.reversalRound&&R%2===0)||(R>=d.reversalRound&&R%2===1))return n-c;return c+1}return(!d.reversalRound||R<d.reversalRound)?c+1:n-c}
 function flatten(d){let n=d.draftOrder.length,o=[];d.draft.forEach((row,r)=>row.forEach((x,c)=>{if(!x?.player)return;let q=rp(d,r,c),p=players?.[x.player]||{},name=`${p.fn||''} ${p.ln||''}`.trim()||'Unknown Player';o.push({owner:x.newOwner||d.draftOrder[c],pos:p.pos||'UNK',name,round:r+1,roundPick:q,overall:r*n+q})}));return o}
 function letter(s){if(s>=94)return'A+';if(s>=90)return'A';if(s>=87)return'A-';if(s>=83)return'B+';if(s>=80)return'B';if(s>=77)return'B-';if(s>=73)return'C+';if(s>=70)return'C';if(s>=67)return'C-';if(s>=63)return'D+';if(s>=60)return'D';return'F'}
 function posGrade(a,n){let x=a.length;if(x>=n+2)return'A';if(x>=n+1)return'B+';if(x>=n)return'B';if(x===n-1)return'C';return'D'}
 function verdict(s,best,reach,counts,grades,earlyPicks,valued){let parts=[];parts.push(s>=90?'This was one of the strongest drafts in the league from a draft-day process standpoint.':s>=83?'This was a strong overall draft that combined useful market value with a roster that came out of draft night in good shape.':s>=77?'This was a solid draft overall, although the value profile was more mixed and left a few areas where the roster will need its bets to hit.':s>=70?'This was a middle-of-the-pack draft on process. There were enough sound picks to keep the roster competitive, but the team gave away some value and did not separate itself from the field on draft night.':'This was an aggressive draft with several structural or value concerns. The roster can still work, but it entered the season needing more of its reaches and thinner position groups to outperform expectations.');if(best)parts.push(best.delta>=15?`${best.name} stands out as the clearest win. Landing him at ${best.round}.${String(best.roundPick).padStart(2,'0')} represented roughly ${Math.round(best.delta)} picks of value compared with the FantasyPros Superflex board.`:best.delta>=5?`${best.name} was the best relative value on the board for this team, coming in about ${Math.round(best.delta)} picks later than his FantasyPros Superflex ranking.`:'The draft did not produce a major FantasyPros bargain, so much of the grade depends on roster construction.');if(reach&&reach.delta<=-5)parts.push(`${reach.name} was the most aggressive selection, coming off the board about ${Math.abs(Math.round(reach.delta))} picks earlier than FantasyPros.`);if(counts.QB>=3)parts.push(`In a league that requires two starting quarterbacks, leaving the draft with ${counts.QB} QBs provides valuable insurance.`);else if(counts.QB===2)parts.push('The team satisfied the two-QB requirement, but carrying exactly two quarterbacks leaves less room for injury, bye-week or performance problems.');else parts.push('The largest structural concern is quarterback. Because GGL requires two starting QBs, failing to leave the draft with two usable options creates a weekly lineup problem.');if(counts.WR>=5&&counts.RB>=4)parts.push(`The roster also came away with healthy volume at both RB and WR (${counts.RB} RBs and ${counts.WR} WRs).`);else if(counts.WR<4||counts.RB<3)parts.push(`Depth is less comfortable at the skill positions, with ${counts.RB} RBs and ${counts.WR} WRs drafted.`);parts.push(valued.length>=10?'Overall, enough of the draft matched the FantasyPros benchmark to make this a fairly complete process grade.':'The FantasyPros match rate is more limited for this roster, so the grade should be read primarily as a draft-day process and construction evaluation.');return parts.join(' ')}
 function score(t,y){let s=75,good=[],bad=[],by=p=>t.picks.filter(x=>x.pos===p),qb=by('QB'),rb=by('RB'),wr=by('WR'),te=by('TE'),k=by('K'),def=by('DEF'),map=rankMap(y);const valued=t.picks.map(p=>({...p,ext:map[norm(p.name)]})).filter(p=>p.ext);const weighted=valued.map(p=>{let w=p.round<=3?1.5:p.round<=6?1:.65;return{...p,delta:p.ext-p.overall,w}});let wsum=weighted.reduce((a,p)=>a+p.w,0),avg=wsum?weighted.reduce((a,p)=>a+p.delta*p.w,0)/wsum:0;s+=Math.max(-14,Math.min(14,avg/2.5));const best=[...weighted].sort((a,b)=>b.delta-a.delta)[0],reach=[...weighted].sort((a,b)=>a.delta-b.delta)[0];if(best?.delta>=8)good.push(`${best.name} was +${Math.round(best.delta)} picks of value vs FantasyPros`);if(reach?.delta<=-8)bad.push(`${reach.name} went ${Math.abs(Math.round(reach.delta))} picks ahead of FantasyPros`);if(qb.length>=2)s+=3;else{s-=12;bad.push('Did not draft two starting QBs')}if(qb.length>=3)s+=1;if(rb.length>=3)s+=2;else{s-=3;bad.push('Thin RB room')}if(wr.length>=4)s+=3;else if(wr.length<3){s-=4;bad.push('Thin WR room')}if(te.length)s+=2;else{s-=4;bad.push('No TE drafted')}if(t.picks.some(x=>['K','DEF'].includes(x.pos)&&x.round<=8)){s-=3;bad.push('Early/mid-round pick spent on K/DEF')}if(!good.length)good.push('Roster construction stayed reasonably balanced');s=Math.max(45,Math.min(96,Math.round(s)));let counts={QB:qb.length,RB:rb.length,WR:wr.length,TE:te.length,K:k.length,DEF:def.length},grades={QB:posGrade(qb,2),RB:posGrade(rb,3),WR:posGrade(wr,4),TE:posGrade(te,1)},earlyPicks=t.picks.filter(x=>x.round<=6),early=earlyPicks.map(x=>`${x.round}.${String(x.roundPick).padStart(2,'0')} ${x.pos}`).join(' · ');return{...t,score:s,grade:letter(s),good:good.slice(0,3),bad:bad.slice(0,3),counts,best,reach,coverage:valued.length,grades,early,verdict:verdict(s,best,reach,counts,grades,earlyPicks,valued)}}
 function analyze(d){let picks=flatten(d),teams=d.draftOrder.filter(Boolean).map(id=>({rosterID:id,picks:picks.filter(p=>String(p.owner)===String(id))})),out=teams.map(t=>score(t,+d.year)).sort((a,b)=>b.score-a.score);return{teams:out,top:out.slice(0,3),sourceCount:(externalLists[+d.year]||[]).length}}
 const pick=p=>p?`${p.round}.${String(p.roundPick).padStart(2,'0')}`:'—';
</script>

<div class="wrap">
<section class="intro"><h2>🧠 GGL Draft Report Cards</h2><p>Grades compare actual GGL picks against <strong>FantasyPros preseason Superflex rankings</strong> for that season, then adjust for full-roster construction and GGL's true 2-QB requirement.</p></section>
{#if drafts.length}<nav>{#each drafts as d}<button class:active={String(selectedYear)===String(d.year)} onclick={()=>selectedYear=d.year}>{d.year}</button>{/each}</nav>{/if}
{#if analysis}
<div class="source">FantasyPros benchmark coverage: top {analysis.sourceCount} preseason Superflex players for {selectedYear}</div>
<h3>{selectedYear} Draft Grades</h3>
<div class="top">{#each analysis.top as t,i}<div><b>#{i+1}</b> {getTeamNameFromTeamManagers(leagueTeamManagers,t.rosterID,selectedYear)} <strong>{t.grade}</strong></div>{/each}</div>
<div class="grid">{#each analysis.teams as t}<details class="teamCard"><summary><img src={getAvatarFromTeamManagers(leagueTeamManagers,t.rosterID,selectedYear)} alt=""><span class="teamSummary"><b>{getTeamNameFromTeamManagers(leagueTeamManagers,t.rosterID,selectedYear)}</b><small>{t.coverage} picks matched to FantasyPros rankings</small></span><span class="summaryGrade"><b>{t.grade}</b><small>{t.score}/100</small></span><span class="chevron">⌄</span></summary><div class="teamDetails">
<div class="drafted"><small>Drafted players</small><div class="pickGrid">{#each t.picks as p}<div class="draftPick"><span class="pickNo">{pick(p)}</span><span class="playerName">{p.name}</span><span class="position">{p.pos}</span></div>{/each}</div></div>
<div class="pos">{#each Object.entries(t.counts) as [p,c]}{#if c}<span>{p} <b>{c}</b></span>{/if}{/each}</div><div class="subgrades"><span>QB <b>{t.grades.QB}</b></span><span>RB <b>{t.grades.RB}</b></span><span>WR <b>{t.grades.WR}</b></span><span>TE <b>{t.grades.TE}</b></span></div><div class="values">{#if t.best}<div><small>Best FantasyPros value</small><b>{t.best.name} · {pick(t.best)}</b><span>+{Math.round(t.best.delta)} picks</span></div>{/if}{#if t.reach}<div><small>Biggest reach</small><b>{t.reach.name} · {pick(t.reach)}</b><span>{Math.abs(Math.round(t.reach.delta))} picks early</span></div>{/if}</div><div class="early"><small>Early-round build</small><p>{t.early}</p></div><div class="notes"><section><h4>Strengths</h4>{#each t.good as x}<p>✓ {x}</p>{/each}</section><section><h4>Needs work</h4>{#if t.bad.length}{#each t.bad as x}<p>• {x}</p>{/each}{:else}<p>• No major flags</p>{/if}</section></div><div class="verdict"><small>Draft verdict</small><p>{t.verdict}</p></div></div></details>{/each}</div>
<p class="method">FantasyPros value is weighted most heavily in the early rounds. Positional grades evaluate depth and starter coverage; the overall grade combines market value with roster construction. Historical drafts are judged against preseason expectations from that season, not hindsight.</p>
{/if}</div>

<style>
.wrap{width:95%;max-width:1100px;margin:auto}.intro,.teamCard,.top>div{border:1px solid var(--ccc);background:var(--fff);border-radius:16px}.intro{padding:18px}.intro h2{margin:0}.intro p{margin:8px 0 0;line-height:1.5;opacity:.7}nav{display:flex;gap:8px;margin:14px 0}nav button{border:1px solid var(--ccc);background:var(--fff);color:inherit;border-radius:999px;padding:8px 15px;font-weight:800;cursor:pointer}nav button.active{background:var(--blueTwo);color:#fff}.source,.method{font-size:.78rem;opacity:.65}.top{display:grid;grid-template-columns:repeat(3,1fr);gap:10px;margin:12px 0 18px}.top>div{padding:12px}.top strong{float:right}.grid{display:grid;gap:12px}.teamCard{overflow:hidden}.teamCard summary{display:flex;align-items:center;gap:12px;padding:14px;cursor:pointer;list-style:none}.teamCard summary::-webkit-details-marker{display:none}.teamCard summary img{width:44px;height:44px;border-radius:50%;object-fit:cover}.teamSummary{display:flex;flex-direction:column;flex:1;min-width:0}.teamSummary small,.summaryGrade small{opacity:.6;font-size:.72rem}.summaryGrade{display:flex;flex-direction:column;text-align:center}.summaryGrade b{font-size:1.35rem}.chevron{font-size:1.3rem;transition:.2s}.teamCard[open] .chevron{transform:rotate(180deg)}.teamDetails{border-top:1px solid var(--ccc);padding:16px}.drafted{margin-bottom:16px}.drafted>small,.early>small,.verdict>small{display:block;text-transform:uppercase;letter-spacing:.08em;font-weight:800;opacity:.6;margin-bottom:8px}.pickGrid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:6px 10px}.draftPick{display:grid;grid-template-columns:48px 1fr auto;align-items:center;gap:8px;padding:8px 10px;border:1px solid var(--ccc);border-radius:10px;background:var(--f8f8f8)}.pickNo{font-weight:900;font-size:.78rem}.playerName{font-weight:700;min-width:0}.position{font-size:.68rem;font-weight:900;opacity:.65}.pos,.subgrades{display:flex;gap:8px;flex-wrap:wrap;margin:10px 0}.pos span,.subgrades span{border:1px solid var(--ccc);border-radius:999px;padding:5px 9px;font-size:.75rem}.values,.notes{display:grid;grid-template-columns:1fr 1fr;gap:10px;margin:12px 0}.values>div,.notes section,.early,.verdict{border:1px solid var(--ccc);border-radius:12px;padding:12px}.values small,.values b,.values span{display:block}.values span{font-size:.75rem;opacity:.65}.early p,.verdict p,.notes p{margin:6px 0;line-height:1.5}.notes h4{margin:0 0 8px}.method{line-height:1.5;margin:16px 4px 30px}
@media(max-width:700px){.top{grid-template-columns:1fr}.pickGrid{grid-template-columns:repeat(2,minmax(0,1fr));gap:6px}.values,.notes{grid-template-columns:1fr}.teamCard summary{padding:12px 10px}.teamDetails{padding:12px}.draftPick{grid-template-columns:36px minmax(0,1fr);grid-template-areas:'pick name' 'pick pos';column-gap:6px;row-gap:1px;padding:7px 8px;min-height:42px}.pickNo{grid-area:pick;font-size:.7rem;align-self:center}.playerName{grid-area:name;font-size:.72rem;line-height:1.1;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.position{grid-area:pos;font-size:.58rem}}
</style>